import{_ as n,a0 as o,w as p,s as r,ao as d,I as l,x as s,a1 as t,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何更改 Linux 的 I/O 调度器 | LCTT x X-CMD","titleTemplate":false,"description":"如何更改 Linux 的 I/O 调度器 | LCTT (201703) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何更改 Linux 的 I/O 调度器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何更改 Linux 的 I/O 调度器 | LCTT (201703) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201703/20160104 How to Change Linux IO Scheduler","title":"如何更改 Linux 的 I/O 调度器","tag":"201703","desc":""},"relativePath":"201703/20160104 How to Change Linux IO Scheduler.md","filePath":"[post].md"}'),u={name:"201703/20160104 How to Change Linux IO Scheduler.md"};function h(g,e,c,b,k,m){const i=o("Link");return p(),r("div",null,[e[13]||(e[13]=d(`<h1 id="如何更改-linux-的-i-o-调度器" tabindex="-1">如何更改 Linux 的 I/O 调度器 <a class="header-anchor" href="#如何更改-linux-的-i-o-调度器" aria-label="Permalink to “如何更改 Linux 的 I/O 调度器”">​</a></h1><p>Linux 的 I/O 调度器是一个从存储卷以块式 I/O 访问的进程，有时也叫磁盘调度器。Linux I/O 调度器的工作机制是控制块设备的请求队列：确定队列中哪些 I/O 的优先级更高以及何时下发 I/O 到块设备，以此来减少磁盘寻道时间，从而提高系统的吞吐量。</p><p>目前 Linux 上有如下几种 I/O 调度算法：</p><ol><li>noop - 通常用于内存存储的设备。</li><li>cfq - 绝对公平调度器。进程平均使用IO带宽。</li><li>Deadline - 针对延迟的调度器，每一个 I/O，都有一个最晚执行时间。</li><li>Anticipatory - 启发式调度，类似 Deadline 算法，但是引入预测机制提高性能。</li></ol><p>查看设备当前的 I/O 调度器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /sys/block/&lt;Disk_Name&gt;/queue/scheduler</span></span></code></pre></div><p>假设磁盘名称是 <code>/dev/sdc</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /sys/block/sdc/queue/scheduler</span></span>
<span class="line"><span>noop anticipatory deadline [cfq]</span></span></code></pre></div><h3 id="如何改变硬盘设备-i-o-调度器" tabindex="-1">如何改变硬盘设备 I/O 调度器 <a class="header-anchor" href="#如何改变硬盘设备-i-o-调度器" aria-label="Permalink to “如何改变硬盘设备 I/O 调度器”">​</a></h3><p>使用如下指令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># echo {SCHEDULER-NAME} &gt; /sys/block/&lt;Disk_Name&gt;/queue/scheduler</span></span></code></pre></div><p>比如设置 noop 调度器:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># echo noop &gt; /sys/block/sdc/queue/scheduler</span></span></code></pre></div><p>以上设置重启后会失效，要想重启后配置仍生效，需要在内核启动参数中将 <code>elevator=noop</code> 写入 <code>/boot/grub/menu.lst</code>：</p><h4 id="_1-备份-menu-lst-文件" tabindex="-1">1. 备份 menu.lst 文件 <a class="header-anchor" href="#_1-备份-menu-lst-文件" aria-label="Permalink to “1. 备份 menu.lst 文件”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp -p /boot/grub/menu.lst /boot/grub/menu.lst-backup</span></span></code></pre></div><h4 id="_2-更新-boot-grub-menu-lst" tabindex="-1">2. 更新 /boot/grub/menu.lst <a class="header-anchor" href="#_2-更新-boot-grub-menu-lst" aria-label="Permalink to “2. 更新 /boot/grub/menu.lst”">​</a></h4><p>将 <code>elevator=noop</code> 添加到文件末尾，比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>kernel /vmlinuz-2.6.16.60-0.91.1-smp root=/dev/sysvg/root splash=silent splash=off showopts elevator=noop</span></span></code></pre></div><hr>`,20)),l("p",null,[e[1]||(e[1]=s("via: ",-1)),t(i,{href:"http://linuxroutes.com/change-io-scheduler-linux/"},{default:a(()=>[...e[0]||(e[0]=[s("http://linuxroutes.com/change-io-scheduler-linux/",-1)])]),_:1})]),l("p",null,[e[5]||(e[5]=s("作者：",-1)),t(i,{href:"http://linuxroutes.com/change-io-scheduler-linux/"},{default:a(()=>[...e[2]||(e[2]=[s("UX Techno",-1)])]),_:1}),e[6]||(e[6]=s(" 译者：",-1)),t(i,{href:"https://github.com/honpey"},{default:a(()=>[...e[3]||(e[3]=[s("honpey",-1)])]),_:1}),e[7]||(e[7]=s(" 校对：",-1)),t(i,{href:"https://github.com/wxy"},{default:a(()=>[...e[4]||(e[4]=[s("wxy",-1)])]),_:1})]),l("p",null,[e[10]||(e[10]=s("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[8]||(e[8]=[s("LCTT",-1)])]),_:1}),e[11]||(e[11]=s(" 原创编译，",-1)),t(i,{href:"https://linux.cn/"},{default:a(()=>[...e[9]||(e[9]=[s("Linux中国",-1)])]),_:1}),e[12]||(e[12]=s(" 荣誉推出",-1))])])}const y=n(u,[["render",h]]);export{C as __pageData,y as default};
